    [
        'title' => 'ARBOK-Trinity-Rice (Selective Acid-Mist Pest Control for Rice)',
        'slug' => 'arbok-trinity-rice-selective-acid-mist-pest-control-for-rice',
        'code_slug' => 'arbok-trinity',
        'aliases' => [
            'arbok-trinity',
