    [
        'title' => 'Arbok-K⁰ — Metallic Potassium from Organic Waste under the Zero Waste Discharge Platform',
        'slug' => 'arbok-k0-metallic-potassium-from-organic-waste-under-the-zero-waste-discharge-platform',
        'code_slug' => 'arbok-k0',
        'aliases' => [
